// Funzione per cambiare lingua
function changeLanguage(lang) {
  // Salva la preferenza dell'utente
  localStorage.setItem('preferredLanguage', lang);
  
  // Nascondi il popup se visibile
  const langPopup = document.getElementById('language-popup');
  if (langPopup) langPopup.style.display = 'none';
  
  // Aggiorna il selettore lingua nel banner
  const langSelect = document.getElementById('language-select');
  if (langSelect) langSelect.value = lang;

  // Traduci tutti gli elementi con l'attributo data-translate
  const elements = document.querySelectorAll('[data-translate]');
  elements.forEach(element => {
    const key = element.getAttribute('data-translate');
    const translation = translations[lang] && translations[lang][key];

    if (translation) {
      if (element.tagName === 'INPUT' && element.hasAttribute('placeholder')) {
        element.setAttribute('placeholder', translation);
      } else {
        element.innerHTML = translation; // Usiamo innerHTML per mantenere i tag <strong>
      }
    }
  });
}

// Esponiamo le funzioni e l'oggetto translations globalmente
window.translations = translations;
window.changeLanguage = changeLanguage;
